={
  "query": {{ JSON.stringify($fromAI('consulta', 'Pregunta del usuario reformulada para búsqueda semántica. Usa el vocabulario del documento (ej: "umbral de vibración molino", "cobertura mínima materia prima", "turnos en muelle"), no la pregunta literal.', 'string')) }},
  "filters": {
    "type": "in",
    "key": "dominio",
    "value": {{ JSON.stringify($fromAI('dominios', 'Dominios donde buscar, separados por coma. Valores válidos ÚNICAMENTE: mant (Mantenimiento: criticidad de equipos, sensores, vibración, lubricación, órdenes de mantenimiento), comp (Compras: abastecimiento, inventario mínimo, stock crítico, proveedores, buffers), logi (Logística: despachos, estados de pedido, turnos de muelle, notificación a clientes), prod (Producción/TD: planeación de demanda, OEE, cumplimiento de plan, tablero de planeación). Si la pregunta cruza áreas incluye varios, ej: "logi,prod". Si no estás seguro, incluye los cuatro.', 'string').split(',').map(d => d.trim().toLowerCase()).filter(d => ['mant','comp','logi','prod'].includes(d))) }}
  },
  "max_num_results": 2
}
